#!/usr/bin/env python3
"""Low-memory wrapper for the 60s falsification suite."""
import argparse,json,os,time
from pathlib import Path
import duckdb,numpy as np,pandas as pd
import scripts.github_phase2_stress60 as b

def q(c,s): return c.execute(s).fetchdf()
def js(x):
 if isinstance(x,(np.integer,)): return int(x)
 if isinstance(x,(np.floating,)): return None if not np.isfinite(x) else float(x)
 if isinstance(x,pd.Timestamp): return x.isoformat()
 return x
def make_panel(c,tp):
 return q(c,f"""WITH tok AS(SELECT mint,detected_at,creator,creator_past_tokens,creator_past_rugs,initial_buy_sol,initial_holder_count,initial_gini,CASE WHEN coalesce(top10_pct_suspect,false) THEN NULL ELSE coalesce(initial_top1_pct_corrected,initial_top1_pct) END initial_top1_pct_model,CASE WHEN coalesce(top10_pct_suspect,false) THEN NULL ELSE coalesce(initial_top5_pct_corrected,initial_top5_pct) END initial_top5_pct_model,CASE WHEN coalesce(top10_pct_suspect,false) THEN NULL ELSE coalesce(initial_top10_pct_corrected,initial_top10_pct) END initial_top10_pct_model,coalesce(dev_buy_pct_corrected,dev_buy_pct) dev_buy_pct_model,launch_snipe_delta_sol,CAST(coalesce(is_mayhem_mode,false) AS INTEGER) is_mayhem_mode,CAST(coalesce(is_cashback_enabled,false) AS INTEGER) is_cashback_enabled,extract(hour from detected_at)::INTEGER hour_utc,extract(dow from detected_at)::INTEGER dow_utc FROM read_parquet('{tp}')),x AS(SELECT r.mint,r.user_wallet,r.is_buy,r.sol_amount,r.token_amount,r.price_sol,r.market_cap_sol,r.seconds_since_launch,tok.creator,(r.user_wallet<>'{b.SYS}') human,(r.sol_amount>0 AND r.token_amount>0 AND r.price_sol>0 AND r.sol_amount/(r.token_amount*r.price_sol) BETWEEN .01 AND 100) valid_sol FROM early60 r JOIN tok USING(mint)),g AS(SELECT mint,count(*) FILTER(WHERE human) human_trades,count(*) FILTER(WHERE human AND is_buy) buys,count(*) FILTER(WHERE human AND NOT is_buy) sells,count(DISTINCT user_wallet) FILTER(WHERE human) unique_wallets,count(DISTINCT user_wallet) FILTER(WHERE human AND is_buy) unique_buyers,count(DISTINCT user_wallet) FILTER(WHERE human AND NOT is_buy) unique_sellers,sum(CASE WHEN human AND valid_sol THEN sol_amount ELSE 0 END) valid_volume_sol,sum(CASE WHEN human AND valid_sol AND is_buy THEN sol_amount ELSE 0 END) buy_volume_sol,sum(CASE WHEN human AND valid_sol AND NOT is_buy THEN sol_amount ELSE 0 END) sell_volume_sol,count(*) FILTER(WHERE human AND seconds_since_launch>30) recent_trades,count(*) FILTER(WHERE human AND seconds_since_launch<=30) prior_trades,count(DISTINCT user_wallet) FILTER(WHERE human AND is_buy AND seconds_since_launch>30) recent_buyers,count(DISTINCT user_wallet) FILTER(WHERE human AND is_buy AND seconds_since_launch<=30) prior_buyers,sum(CASE WHEN human AND valid_sol AND seconds_since_launch>30 THEN sol_amount ELSE 0 END) recent_volume_sol,sum(CASE WHEN human AND valid_sol AND seconds_since_launch<=30 THEN sol_amount ELSE 0 END) prior_volume_sol,arg_min(price_sol,seconds_since_launch) FILTER(WHERE price_sol>0) first_price_sol,arg_max(price_sol,seconds_since_launch) FILTER(WHERE price_sol>0) entry_price_sol,min(price_sol) FILTER(WHERE price_sol>0) min_price_sol,max(price_sol) FILTER(WHERE price_sol>0) max_price_sol,arg_max(market_cap_sol,seconds_since_launch) FILTER(WHERE market_cap_sol>0) market_cap_sol,max(seconds_since_launch) FILTER(WHERE human) last_human_sec,count(*) FILTER(WHERE human AND user_wallet=creator) creator_trades,sum(CASE WHEN human AND user_wallet=creator AND is_buy AND valid_sol THEN sol_amount ELSE 0 END) creator_buy_volume_sol FROM x GROUP BY mint) SELECT tok.*,g.*,buy_volume_sol/(sell_volume_sol+.01) buy_sell_volume_ratio,(recent_trades-prior_trades)/(prior_trades+1.0) tx_acceleration,(recent_buyers-prior_buyers)/(prior_buyers+1.0) buyer_acceleration,(recent_volume_sol-prior_volume_sol)/(prior_volume_sol+.01) volume_acceleration,entry_price_sol/first_price_sol-1 price_return,max_price_sol/nullif(min_price_sol,0) price_range_ratio,60-last_human_sec last_trade_gap_sec FROM tok JOIN g USING(mint) WHERE entry_price_sol>0""")
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--out',default='reports/stress60');a=ap.parse_args();o=Path(a.out);o.mkdir(parents=True,exist_ok=True);r=Path(os.environ.get('RUNNER_TEMP','/tmp'))/'stress60_lowmem';t0=time.time();sh=b.acquire(r);c=duckdb.connect(str(r/'s.duckdb'));c.execute("SET threads=1");c.execute("SET memory_limit='3.6GB'");c.execute("SET preserve_insertion_order=false");(r/'spill').mkdir(exist_ok=True);c.execute(f"SET temp_directory='{r/'spill'}'");tg=str(r/'trades/*.parquet');tp=str(r/'tokens.parquet');mg=str(r/'migrations.parquet');pg=str(r/'postgard_snapshots.parquet');og=str(r/'postgard_outcomes.parquet')
 c.execute(f"CREATE TABLE early60 AS SELECT mint,user_wallet,is_buy,sol_amount,token_amount,price_sol,market_cap_sol,seconds_since_launch FROM read_parquet('{tg}') WHERE seconds_since_launch BETWEEN 0 AND 60")
 c.execute(f"CREATE TABLE pre AS SELECT mint,seconds_since_launch::DOUBLE sec,price_sol::DOUBLE price FROM read_parquet('{tg}') WHERE price_sol>0 AND seconds_since_launch IS NOT NULL");c.execute("CREATE TABLE lp AS SELECT mint,arg_max(price,sec) p FROM pre GROUP BY mint");c.execute(f"CREATE TABLE post AS SELECT x.mint,(coalesce(t.seconds_to_graduation,m.seconds_to_graduation)+x.seconds_since_graduation)::DOUBLE sec,(lp.p*(x.price_usd/y.price_at_grad_usd))::DOUBLE price FROM read_parquet('{pg}') x JOIN lp USING(mint) LEFT JOIN read_parquet('{tp}') t USING(mint) LEFT JOIN read_parquet('{mg}') m USING(mint) JOIN read_parquet('{og}') y USING(mint) WHERE x.price_usd>0 AND y.price_at_grad_usd>0 AND x.seconds_since_graduation>=0 AND NOT coalesce(x.incomplete_data,false) AND coalesce(t.seconds_to_graduation,m.seconds_to_graduation) IS NOT NULL");c.execute('CREATE VIEW price_path AS SELECT * FROM pre UNION ALL SELECT * FROM post')
 p=b.labels(c,make_panel(c,tp));p=p[p.future_points>0].copy();p.detected_at=pd.to_datetime(p.detected_at,utc=True);res={'eligible':len(p),'target_counts':{str(t):int(p[f"hit_{t}x"].sum()) for t in b.TARGETS},'folds':{},'execution':{},'elapsed_to_panel_sec':time.time()-t0};rows=[]
 for a1,b1,nm in b.FOLDS:
  tr,te,cut,end=b.fold(p,a1,b1);seen=set(tr.creator.dropna().astype(str));u=te[~te.creator.fillna('').astype(str).isin(seen)].copy();fr={'cutoff':cut,'test_end':end,'n_train':len(tr),'n_test':len(te),'n_unseen_creator':len(u),'targets':{}}
  for t in b.TARGETS:
   col=f'hit_{t}x';item={'all':b.score(tr,te,b.ALL,col),'logit_all':b.score(tr,te,b.ALL,col,'logit')}
   if t in (10,100):item['no_price_mcap']=b.score(tr,te,b.SETS['no_price_mcap'],col);item['flow_only']=b.score(tr,te,b.FLOW,col);item['unseen_creator_all']=b.score(tr,u,b.ALL,col)
   fr['targets'][str(t)]=item
   for k,v in item.items():
    if v and v.get('top1'):rows.append({'fold':nm,'target':t,'model':k,'n_test':v['n'],'base_rate':v['base_rate'],'top1_rate':v['top1']['rate'],'top1_lift':v['top1']['lift'],'top100_hits':v['top100']['hits'],'auc':v.get('auc'),'ap':v.get('ap')})
  res['folds'][nm]=fr
 for d in (0,15,30,60):res['execution'][f'delay_{d}s']=b.eval_scenario(p,b.scenario(c,p,delay=d,target=100))
 for z in (.05,.10,.20):res['execution'][f'adverse_{int(z*100)}pct']=b.eval_scenario(p,b.scenario(c,p,penalty=z,target=100))
 h=pd.DataFrame(rows);h.to_csv(o/'stress_headlines.csv',index=False);summ=[]
 if len(h):
  for (t,m),g in h.groupby(['target','model']):summ.append({'target':int(t),'model':m,'folds':len(g),'median_top1_lift':float(g.top1_lift.median()),'min_top1_lift':float(g.top1_lift.min()),'max_top1_lift':float(g.top1_lift.max()),'sum_top100_hits':int(g.top100_hits.sum())})
 res['summary']=summ;res['elapsed_sec']=time.time()-t0;res['guard']='Historical stress test only; live execution remains unproven.';(o/'STRESS_RESULT.json').write_text(json.dumps(res,indent=2,default=js));pd.DataFrame(summ).to_csv(o/'fold_summary.csv',index=False);print(json.dumps({'eligible':len(p),'elapsed_sec':res['elapsed_sec'],'summary_rows':len(summ)},indent=2))
if __name__=='__main__':main()
